  `holiday_name` varchar(255) DEFAULT NULL,
  `reason` varchar(255) DEFAULT NULL,
  `declared_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `comp_off_working_days_work_date_unique` (`work_date`),
  KEY `comp_off_working_days_declared_by_foreign` (`declared_by`),
  KEY `comp_off_working_days_work_date_index` (`work_date`),
  CONSTRAINT `comp_off_working_days_declared_by_foreign` FOREIGN KEY (`declared_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
