INSERT INTO `settings` VALUES (1,'ot_trigger_time','19:00','OT Trigger Time','Minimum checkout time (HH:MM, 24-hr) for an employee to be eligible for OT calculation.','time','ot','2026-05-18 23:28:16','2026-05-21 22:40:42'),(2,'ot_baseline_time','18:15','OT Baseline Time','OT hours are counted from this time onwards (HH:MM, 24-hr). Typically office closing time.','time','ot','2026-05-18 23:28:16','2026-05-21 22:40:42'),(3,'office_start_time','09:00','Office Start Time','Check-in time considered late after this (HH:MM, 24-hr format)','time','ot','2026-05-21 22:56:56','2026-05-21 22:56:56'),(4,'daily_grace_minutes','15','Daily Late Grace (minutes)','Minutes after office start before check-in is counted as late. E.g. 15 means 09:15 is the late threshold when office starts at 09:00.','integer','grace',NULL,'2026-05-26 01:47:47'),(5,'monthly_grace_minutes','90','Monthly Late Permission (minutes)','Total late minutes allowed per month before the 2× deduction penalty applies.','integer','grace',NULL,'2026-05-26 01:47:47');
